        D_dmi_mj_m2=spin_params['magnetic_domain_wall']['dzyaloshinskii_moriya_constant_mj_m2'],
        K_u_kj_m3=spin_params['magnetic_domain_wall']['perpendicular_anisotropy_kj_m3']
    )
    sigma_wall = dw.wall_energy()
    H_walker = dw.walker_breakdown_field()
